// PokePoke pi integration - auto-generated by `poke-hook --install-pi`.
// pokepoke-plugin-marker
// Do not edit by hand; re-run Connect from the PokePoke tray to regenerate.
//
// Forwards pi session lifecycle events to the local PokePoke app via the
// poke-hook binary. All failures are swallowed so a notification hiccup
// never disrupts your pi session. Plain Node built-ins only (pi runs
// extensions under Node via jiti).
import { spawn } from "node:child_process";

const POKE_HOOK = "__POKE_HOOK_BIN__";

// Dedupe SessionStart per session id within this extension instance:
// each SessionStart triggers a Ghostty terminal_id capture server-side,
// and a duplicate capture can race and bind the wrong tab.
const seenSessions = new Set();
const DEDUP_CAP = 2000;
function remember(set, id) {
  if (set.size >= DEDUP_CAP) set.clear();
  set.add(id);
}

function forward(payload) {
  try {
    const child = spawn(POKE_HOOK, ["--source=pi"], {
      stdio: ["pipe", "ignore", "ignore"],
    });
    child.on("error", () => {});
    child.stdin.on("error", () => {});
    child.stdin.write(JSON.stringify(payload));
    child.stdin.end();
  } catch {
    // never let a notification failure surface into pi
  }
}

// ---- StopFailure: provider errors that end a turn ----
// pi 0.83.0 agent_end carries the final assistant message, whose stopReason
// distinguishes "error" (provider/API failure) from "aborted" (user cancel).
// agent_settled fires only after auto-retry / compaction / queued follow-ups
// are all drained, so at settle we split on the LAST agent_end's stopReason:
// "error" -> StopFailure (server last_failed + failed sound), anything else
// -> plain Stop. Intermediate errors inside the retry budget get overwritten
// by the eventual success, so no false positives (grok review §1.6).
const MAX_ERROR_DETAIL = 300;
function truncateDetail(s) {
  if (typeof s !== "string" || s.length <= MAX_ERROR_DETAIL) return s || "";
  return s.slice(0, MAX_ERROR_DETAIL - 3) + "...";
}
function errorDetailOf(message) {
  if (!message) return "";
  if (typeof message.errorMessage === "string" && message.errorMessage) {
    return message.errorMessage;
  }
  const content = message.content;
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    const text = content
      .filter((p) => p && p.type === "text" && typeof p.text === "string")
      .map((p) => p.text)
      .join(" ");
    if (text) return text;
  }
  return "";
}
function finalAssistantMessage(messages) {
  if (!Array.isArray(messages)) return undefined;
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i] && messages[i].role === "assistant") return messages[i];
  }
  return undefined;
}

export default function (pi) {
  // PokePoke tracks interactive TUI sessions only: print/rpc/json runs
  // have no terminal pane to jump back to.
  let sessionId = undefined;
  let cwd = "";
  // Turn-failure / abort state: set by agent_end, consumed/reset by agent_settled.
  // turnFailed = provider error (stopReason "error") -> StopFailure.
  // turnAborted = user cancel (stopReason "aborted") -> Stop + aborted:true
  //   (server T1 链路据此抑制"完成"音,与 cursor aborted 对齐)。
  // 两者互斥:以 settle 前最后一个 agent_end 的 stopReason 为准。
  let turnFailed = false;
  let turnAborted = false;
  let turnErrorDetail = "";

  pi.on("session_start", async (_event, ctx) => {
    try {
      if (ctx?.mode !== "tui") return;
      sessionId = ctx?.sessionManager?.getSessionId?.() ?? undefined;
      cwd = ctx?.cwd ?? "";
      if (!sessionId) return; // ephemeral (--no-session): no stable identity
      if (seenSessions.has(sessionId)) return;
      remember(seenSessions, sessionId);
      forward({ hook_event_name: "SessionStart", session_id: sessionId, cwd });
    } catch {}
  });

  pi.on("before_agent_start", async () => {
    try {
      if (!sessionId) return;
      turnFailed = false;
      turnAborted = false;
      turnErrorDetail = "";
      forward({ hook_event_name: "UserPromptSubmit", session_id: sessionId, cwd });
    } catch {}
  });

  // agent_end: split on the final assistant message's stopReason.
  // Retries / compaction / queued follow-ups re-enter the agent loop and
  // emit another agent_end, so only the last one before settle matters.
  pi.on("agent_end", async (event) => {
    try {
      if (!sessionId) return;
      const last = finalAssistantMessage(event && event.messages);
      const stopReason = last && last.stopReason;
      if (stopReason === "error") {
        turnFailed = true;
        turnAborted = false;
        turnErrorDetail = errorDetailOf(last);
      } else if (stopReason === "aborted") {
        // 用户主动取消:不是 provider 失败,但也不是正常完成——
        // settle 时发 Stop + aborted:true,server 抑制"完成"音。
        turnFailed = false;
        turnAborted = true;
        turnErrorDetail = "";
      } else {
        // success / 其它 stopReason:正常完成,两者皆否。
        turnFailed = false;
        turnAborted = false;
        turnErrorDetail = "";
      }
    } catch {}
  });

  // Auxiliary signal: a provider returned 429/5xx. Only enriches the failure
  // detail; never the failure verdict (transient errors are absorbed by
  // retries, agent_end's stopReason is the final word). Skip when the detail
  // already carries that status (errorMessage usually repeats it).
  pi.on("after_provider_response", async (event) => {
    try {
      if (!sessionId) return;
      const status = event && event.status;
      if (typeof status === "number" && (status === 429 || status >= 500)) {
        if (!turnErrorDetail.includes("HTTP " + status)) {
          turnErrorDetail = turnErrorDetail
            ? "HTTP " + status + " · " + turnErrorDetail
            : "HTTP " + status;
        }
      }
    } catch {}
  });

  // agent_settled (NOT agent_end): pi may auto-retry, auto-compact, or
  // drain queued follow-ups after agent_end. agent_settled means it will
  // not continue on its own - the correct "done, waiting for user" signal.
  pi.on("agent_settled", async () => {
    try {
      if (!sessionId) return;
      if (turnFailed) {
        turnFailed = false;
        forward({
          hook_event_name: "StopFailure",
          session_id: sessionId,
          cwd,
          reason: "provider_error",
          detail: truncateDetail(turnErrorDetail) || "Provider request failed",
        });
        turnErrorDetail = "";
        return;
      }
      if (turnAborted) {
        // 用户取消:发 Stop 但带 aborted:true,server 写 aborted_at 并在
        // 5s 窗口内抑制"完成"音(及同轮 last_failed artifact echo),
        // 与 cursor T1(brief 20260805-t1-cursor-aborted)行为一致。
        turnAborted = false;
        forward({ hook_event_name: "Stop", session_id: sessionId, cwd, aborted: true });
        return;
      }
      forward({ hook_event_name: "Stop", session_id: sessionId, cwd });
    } catch {}
  });

  // reason: "quit" | "reload" | "new" | "resume" | "fork" - in every case
  // this session id stops being live here; a replacement session (if any)
  // re-registers via its own session_start in a fresh extension instance.
  pi.on("session_shutdown", async () => {
    try {
      if (!sessionId) return;
      forward({ hook_event_name: "SessionEnd", session_id: sessionId, cwd });
      sessionId = undefined;
    } catch {}
  });
}
